module LocalLikelihoodTest

using Test
using KernelSmoothing

# reference values from R's glm, generated by data/locallik_golden.R
include(joinpath(@__DIR__, "data", "locallik_golden.jl"))

# 500 observations; constants of 30 bits, so that R computes the same data
const I = 1:500
const X = mod.(I .* (round(0.6180339887498949 * 2^30) / 2^30), 1)
const PROB = 1 ./ (1 .+ exp.(-(2 .* sin.(2π .* X))))
const RESPONSES = Dict("yb" => Float64.(mod.(I .* (round(0.7548776662466927 * 2^30) / 2^30), 1) .< PROB),
                       "yp" => floor.(-log.(1 .- mod.(I .* (round(0.5698402909980532 * 2^30) / 2^30), 1)) .* exp.(1 .+ sin.(2π .* X))))
const W = 1.0 .+ mod.(I, 3)

@testset "agrees with glm" begin
  for c in LOCALLIK
    m = fit(LocalLikelihood, X, RESPONSES[c.y]; family = c.family, degree = c.degree, bandwidth = c.h,
            points = c.points, weights = c.weighted ? W : nothing)
    @test coef(m) ≈ c.eta rtol = 1e-10
    @test stderror(m) ≈ c.se rtol = 1e-10
  end
end

@testset "local likelihood" begin
  yb = RESPONSES["yb"]
  # the local constant logit fit is the logit of the kernel-weighted mean
  m0 = fit(LocalLikelihood, X, yb; degree = 0, bandwidth = 0.2, points = [0.3])
  kw = EpanechnikovKernel().((X .- 0.3) ./ 0.2)
  @test predict(m0)[1] ≈ sum(kw .* yb) / sum(kw) rtol = 1e-12
  m = fit(LocalLikelihood, X, yb; bandwidth = 0.2, points = [0.1, 0.5, 0.9])
  ci = confint(m)
  @test all(0 .< ci[:, 1] .< predict(m) .< ci[:, 2] .< 1)
  @test confint(m; scale = :linear) ≈ hcat(coef(m) .- 1.959963984540054 .* stderror(m), coef(m) .+ 1.959963984540054 .* stderror(m))
  # a bandwidth per point
  @test coef(fit(LocalLikelihood, X, yb; bandwidth = [0.2, 0.3], points = [0.1, 0.5]))[2] ≈
        coef(fit(LocalLikelihood, X, yb; bandwidth = 0.3, points = [0.5]))[1]
  # cross-validation: the one-step leave-one-out fits are close to the refits
  d = SmoothingData(X, RESPONSES["yp"])
  k = EpanechnikovKernel()
  for j in (1, 77, 250)   # positions in the sorted order of the data
    keep = setdiff(I, d.perm[j])
    η = KernelSmoothing._llfit(SmoothingData(X[keep], RESPONSES["yp"][keep]), k, d.x[j], 0.2, 1, :poisson).eta
    @test KernelSmoothing._llfit(d, k, d.x[j], 0.2, 1, :poisson; loo = j).eta ≈ η rtol = 0.02
  end
  mc = fit(LocalLikelihood, X, yb)
  @test mc.selection.rule == CrossValidation() && 0.05 < mc.h[1] < 0.5
  mp = fit(LocalLikelihood, X, RESPONSES["yp"]; family = :poisson)
  @test 0.05 < mp.h[1] < 0.5 && mp.selection.details.grid[1] > 0.04
  # all responses equal in the window: no maximum
  @test isnan(coef(fit(LocalLikelihood, X, zeros(500); bandwidth = 0.2, points = [0.5]))[1])
  @test isnan(coef(fit(LocalLikelihood, X, yb; bandwidth = 0.1, points = [3.0]))[1])
  @test nobs(m) == 500 && bandwidth(m) == fill(0.2, 3)
  @test startswith(sprint(show, m), "LocalLikelihood(logit, degree 1")
  @inferred fit(LocalLikelihood, X, yb; bandwidth = 0.2, points = [0.5])
end

@testset "errors" begin
  @test_throws ArgumentError fit(LocalLikelihood, X, RESPONSES["yb"]; family = :gamma, bandwidth = 0.2)
  @test_throws ArgumentError fit(LocalLikelihood, X, RESPONSES["yp"]; bandwidth = 0.2)
  @test_throws ArgumentError fit(LocalLikelihood, X, -RESPONSES["yb"]; family = :poisson, bandwidth = 0.2)
  @test_throws ArgumentError fit(LocalLikelihood, X, RESPONSES["yb"]; bandwidth = 0.2, degree = -1)
  @test_throws ArgumentError fit(LocalLikelihood, X, RESPONSES["yb"]; bandwidth = MSEOptimal())
  @test_throws ArgumentError confint(fit(LocalLikelihood, X, RESPONSES["yb"]; bandwidth = 0.2, points = [0.5]); scale = :odds)
end

end
